website.css:
/* ===== Base & Variables ===== */
:root{
  --navy:#0f1b2d;
  --navy-light:#16263e;
  --gold:#c9a24b;
  --gold-light:#e0c17e;
  --cream:#f7f4ee;
  --grey:#5b6472;
  --white:#ffffff;
  --radius:14px;
  --transition: 0.3s ease;
  font-size:16px;
}
*{box-sizing:border-box;}
html,body{margin:0;padding:0;}
body{
  font-family:'Georgia', 'Times New Roman', serif;
  color:var(--navy);
  background:var(--cream);
  line-height:1.6;
}
h1,h2,h3{
  font-family:'Helvetica Neue', Arial, sans-serif;
  font-weight:700;
  margin:0 0 0.5em;
  letter-spacing:-0.02em;
}
p{margin:0 0 1em;}
a{color:inherit;text-decoration:none;}
.section-inner{
  max-width:1140px;
  margin:0 auto;
  padding:0 24px;
}

/* ===== Header ===== */
.site-header{
  position:sticky;
  top:0;
  z-index:100;
  background:rgba(15,27,45,0.95);
  backdrop-filter:blur(6px);
  box-shadow:0 2px 14px rgba(0,0,0,0.15);
}
.header-inner{
  max-width:1140px;
  margin:0 auto;
  padding:16px 24px;
  display:flex;
  align-items:center;
  justify-content:space-between;
}
.brand{
  display:flex;
  align-items:center;
  gap:10px;
  color:var(--white);
  font-family:'Helvetica Neue', Arial, sans-serif;
}
.brand-mark{
  width:38px;height:38px;
  border:2px solid var(--gold);
  border-radius:50%;
  display:flex;
  align-items:center;
  justify-content:center;
  font-weight:700;
  color:var(--gold);
  font-size:0.85rem;
}
.brand-name{
  font-size:1.1rem;
  font-weight:700;
  letter-spacing:0.02em;
}
.brand-name em{
  font-style:normal;
  color:var(--gold-light);
}
.main-nav{position:relative;}
.nav-menu{
  display:flex;
  gap:28px;
  list-style:none;
  margin:0;
  padding:0;
}
.nav-menu a{
  color:var(--white);
  font-family:'Helvetica Neue', Arial, sans-serif;
  font-size:0.95rem;
  position:relative;
  padding:4px 0;
  transition:color var(--transition);
}
.nav-menu a::after{
  content:'';
  position:absolute;
  left:0;bottom:-4px;
  width:0;height:2px;
  background:var(--gold);
  transition:width var(--transition);
}
.nav-menu a:hover,
.nav-menu a:focus{
  color:var(--gold-light);
}
.nav-menu a:hover::after,
.nav-menu a:focus::after{
  width:100%;
}
.nav-toggle{
  display:none;
  flex-direction:column;
  gap:5px;
  background:none;
  border:none;
  cursor:pointer;
  padding:6px;
}
.nav-toggle span{
  width:24px;height:2px;
  background:var(--white);
  display:block;
  transition:transform var(--transition), opacity var(--transition);
}

/* ===== Hero ===== */
.hero{
  position:relative;
  min-height:88vh;
  display:flex;
  align-items:center;
  justify-content:center;
  background:linear-gradient(135deg, var(--navy) 0%, var(--navy-light) 60%, #1d3252 100%);
  overflow:hidden;
  text-align:center;
  padding:80px 24px;
}
.hero-shapes{
  position:absolute;
  inset:0;
  pointer-events:none;
}
.shape{
  position:absolute;
  border-radius:50%;
  opacity:0.18;
  background:radial-gradient(circle at 30% 30%, var(--gold-light), transparent 70%);
}
.shape-1{width:380px;height:380px;top:-100px;left:-100px;}
.shape-2{width:260px;height:260px;bottom:-80px;right:5%;}
.shape-3{width:160px;height:160px;top:40%;right:20%;}
.hero-content{
  position:relative;
  z-index:2;
  max-width:760px;
  color:var(--white);
}
.eyebrow{
  text-transform:uppercase;
  letter-spacing:0.25em;
  font-size:0.75rem;
  color:var(--gold-light);
  font-family:'Helvetica Neue', Arial, sans-serif;
  margin-bottom:18px;
}
.hero h1{
  font-size:clamp(2.5rem, 6vw, 4.5rem);
  margin-bottom:20px;
  color:var(--white);
}
.hero-sub{
  font-size:1.15rem;
  color:#cfd7e3;
  max-width:600px;
  margin:0 auto 32px;
}
.hero-actions{
  display:flex;
  gap:18px;
  justify-content:center;
  flex-wrap:wrap;
}

/* ===== Buttons ===== */
.btn{
  display:inline-block;
  padding:14px 30px;
  border-radius:50px;
  font-family:'Helvetica Neue', Arial, sans-serif;
  font-weight:600;
  font-size:0.95rem;
  transition:all var(--transition);
  border:2px solid transparent;
  cursor:pointer;
}
.btn-primary{
  background:var(--gold);
  color:var(--navy);
}
.btn-primary:hover,
.btn-primary:focus{
  background:var(--gold-light);
  transform:translateY(-2px);
  box-shadow:0 8px 20px rgba(201,162,75,0.35);
}
.btn-ghost{
  background:transparent;
  border-color:rgba(255,255,255,0.5);
  color:var(--white);
}
.btn-ghost:hover,
.btn-ghost:focus{
  border-color:var(--gold-light);
  color:var(--gold-light);
  transform:translateY(-2px);
}

/* ===== About ===== */
.about{
  padding:100px 0;
  background:var(--cream);
}
.about-grid{
  display:grid;
  grid-template-columns:1.2fr 0.8fr;
  gap:60px;
  align-items:center;
}
.about-text h2{
  font-size:2.2rem;
  color:var(--navy);
}
.about-text p{
  color:var(--grey);
  font-size:1.05rem;
}
.note{
  border-left:4px solid var(--gold);
  padding-left:16px;
  font-style:italic;
  color:var(--navy);
}
.about-visual{
  display:flex;
  justify-content:center;
}
.visual-card{
  width:100%;
  max-width:320px;
  background:var(--white);
  border-radius:var(--radius);
  padding:36px 28px;
  box-shadow:0 20px 50px rgba(15,27,45,0.12);
  position:relative;
}
.visual-line{
  display:block;
  height:10px;
  border-radius:6px;
  background:linear-gradient(90deg, var(--navy), var(--navy-light));
  margin-bottom:16px;
  opacity:0.9;
}
.visual-line.short{width:60%;}
.visual-dot{
  position:absolute;
  bottom:-14px;
  right:-14px;
  width:56px;height:56px;
  background:var(--gold);
  border-radius:50%;
  box-shadow:0 10px 25px rgba(201,162,75,0.4);
}

/* ===== Purpose ===== */
.purpose{
  padding:100px 0;
  background:var(--navy);
  color:var(--white);
}
.purpose h2{
  text-align:center;
  font-size:2.2rem;
  margin-bottom:50px;
  color:var(--white);
}
.purpose-cards{
  display:grid;
  grid-template-columns:repeat(3, 1fr);
  gap:30px;
}
.purpose-card{
  background:var(--navy-light);
  border-radius:var(--radius);
  padding:36px 28px;
  border:1px solid rgba(201,162,75,0.2);
  transition:transform var(--transition), box-shadow var(--transition);
}
.purpose-card:hover{
  transform:translateY(-8px);
  box-shadow:0 20px 40px rgba(0,0,0,0.3);
  border-color:var(--gold);
}
.card-index{
  display:inline-block;
  font-family:'Helvetica Neue', Arial, sans-serif;
  font-size:0.85rem;
  color:var(--gold-light);
  letter-spacing:0.1em;
  margin-bottom:12px;
}
.purpose-card h3{
  color:var(--white);
  font-size:1.25rem;
}
.purpose-card p{
  color:#c6ccd6;
  font-size:0.95rem;
  margin:0;
}

/* ===== Languages ===== */
.languages{
  padding:100px 0;
  background:var(--cream);
  text-align:center;
}
.languages h2{
  font-size:2.2rem;
  color:var(--navy);
}
.languages-intro{
  color:var(--grey);
  margin-bottom:50px;
}
.lang-grid{
  display:grid;
  grid-template-columns:repeat(3, 1fr);
  gap:24px;
  text-align:left;
}
.lang-card{
  background:var(--white);
  border-radius:var(--radius);
  padding:28px;
  box-shadow:0 10px 30px rgba(15,27,45,0.08);
  transition:transform var(--transition);
}
.lang-card:hover{
  transform:translateY(-6px);
}
.lang-card h3{
  color:var(--gold);
  font-size:1.05rem;
  margin-bottom:10px;
}
.lang-card p{
  color:var(--grey);
  font-size:0.95rem;
  margin:0;
}

/* ===== CTA ===== */
.cta{
  padding:100px 0;
  background:linear-gradient(135deg, #1d3252, var(--navy));
  color:var(--white);
  text-align:center;
}
.cta h2{
  font-size:2.3rem;
  color:var(--white);
}
.cta p{
  color:#cfd7e3;
  max-width:500px;
  margin:0 auto 30px;
}

/* ===== Footer ===== */
.site-footer{
  background:var(--navy);
  color:#9aa5b4;
  padding:30px 0;
}
.footer-inner{
  display:flex;
  justify-content:space-between;
  align-items:center;
  flex-wrap:wrap;
  gap:10px;
  font-size:0.85rem;
}
.back-to-top{
  color:var(--gold-light);
  font-family:'Helvetica Neue', Arial, sans-serif;
  transition:color var(--transition);
}
.back-to-top:hover,
.back-to-top:focus{
  color:var(--white);
}

/* ===== Responsive ===== */
@media (max-width:900px){
  .about-grid{
    grid-template-columns:1fr;
  }
  .purpose-cards{
    grid-template-columns:1fr 1fr;
  }
  .lang-grid{
    grid-template-columns:1fr 1fr;
  }
}
@media (max-width:700px){
  .nav-menu{
    position:absolute;
    top:64px;
    right:0;
    background:var(--navy);
    flex-direction:column;
    width:220px;
    padding:20px;
    border-radius:0 0 0 12px;
    box-shadow:0 10px 30px rgba(0,0,0,0.3);
    transform:translateX(100%);
    opacity:0;
    visibility:hidden;
    transition:transform var(--transition), opacity var(--transition), visibility var(--transition);
  }
  .nav-menu.open{
    transform:translateX(0);
    opacity:1;
    visibility:visible;
  }
  .nav-toggle{
    display:flex;
  }
  .purpose-cards{
    grid-template-columns:1fr;
  }
  .lang-grid{
    grid-template-columns:1fr;
  }
  .hero-actions{
    flex-direction:column;
    align-items:center;
  }
}
@media (max-width:480px){
  .hero h1{font-size:2.4rem;}
  .brand-name{font-size:0.95rem;}
}

website.javascript:
document.addEventListener('DOMContentLoaded', function () {
  var toggle = document.querySelector('.nav-toggle');
  var menu = document.getElementById('nav-menu');

  if (toggle && menu) {
    toggle.addEventListener('click', function () {
      var isOpen = menu.classList.toggle('open');
      toggle.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    });

    menu.querySelectorAll('a').forEach(function (link) {
      link.addEventListener('click', function () {
        menu.classList.remove('open');
        toggle.setAttribute('aria-expanded', 'false');
      });
    });
  }

  var yearSpan = document.getElementById('year');
  if (yearSpan) {
    yearSpan.textContent = new Date().getFullYear();
  }

  var navLinks = document.querySelectorAll('a[href^="#"]');
  navLinks.forEach(function (link) {
    link.addEventListener('click', function (e) {
      var targetId = link.getAttribute('href');
      if (targetId.length > 1) {
        var target = document.querySelector(targetId);
        if (target) {
          e.preventDefault();
          target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      }
    });
  });

  var header = document.querySelector('.site-header');
  if (header) {
    window.addEventListener('scroll', function () {
      if (window.scrollY > 10) {
        header.style.boxShadow = '0 4px 20px rgba(0,0,0,0.25)';
      } else {
        header.style.boxShadow = '0 2px 14px rgba(0,0,0,0.15)';
      }
    });
  }
});
